def bookUpToTwoOverlapping(requests):
    events = []
    doubles = []
    result = []
    for s, e in requests:
        if any(s < b and a < e for a, b in doubles):
            result.append(0)
            continue
        for a, b in events:
            lo = max(s, a)
            hi = min(e, b)
            if lo < hi:
                doubles.append((lo, hi))
        events.append((s, e))
        result.append(1)
    return result
